      bucket.tokens += tokens;
      bucket.input = (bucket.input ?? 0) + input;
      bucket.output = (bucket.output ?? 0) + output;
      bucket.cacheRead = (bucket.cacheRead ?? 0) + cacheRead;
      bucket.cacheWrite = (bucket.cacheWrite ?? 0) + cacheWrite;
