  const { frames, tornStart } = scanZstdFrames(buffer);
  const parts = [];
  for (const frame of frames) {
    parts.push(zlib.zstdDecompressSync(buffer.subarray(frame.start, frame.end)));
  }
  return parseEventLines(Buffer.concat(parts).toString("utf8"));
