  // headless sessions are covered by the periodic sweep instead).
  ctx.on("session/event", (session, event) => {
    const sessionId = session?.id ?? "?";
    try {
      if (event?.type === "session/title" && typeof event?.data?.title === "string" && event.data.title.trim() !== "") {
