async function browserProfileLeveldbDirs() {
  const local = process.env.LOCALAPPDATA ?? join(homedir(), "AppData", "Local");
  const roots = [
    join(local, "Google", "Chrome", "User Data"),
    join(local, "Microsoft", "Edge", "User Data"),
    join(local, "360ChromeX", "Chrome", "User Data"),
    join(local, "360Chrome", "Chrome", "User Data"),
    join("D:", "360ChromeX", "Chrome", "User Data"),
    join("D:", "360Chrome", "Chrome", "User Data"),
  ];
  const dirs = [];
  for (const root of roots) {
    if (!existsSync(root)) continue;
    const entries = await readdir(root, { withFileTypes: true }).catch(() => []);
    for (const entry of entries) {
      if (!entry.isDirectory()) continue;
      if (entry.name !== "Default" && !/^Profile \d+$/.test(entry.name) && !entry.name.startsWith("user-")) continue;
      const dir = join(root, entry.name, "Local Storage", "leveldb");
      if (existsSync(dir)) dirs.push(dir);
    }
  }
  return dirs;
}

const DEEPSEEK_STORAGE_KEY = Buffer.from("_https://platform.deepseek.com\u0000\u0001userToken");

/** Chromium localStorage stores `userToken` as a JSON object string like `{"value":"..."}`. */
function decodeLocalStorageValue(value) {
  if (value == null) return null;
  const raw = value.toString().slice(1);
  try {
    const parsed = JSON.parse(raw);
    if (parsed !== null && typeof parsed === "object" && typeof parsed.value === "string" && parsed.value.trim() !== "") {
      return parsed.value;
    }
  } catch {}
  return raw.trim() !== "" ? raw : null;
}

function readTokenFromLeveldbDir(leveldbDir) {
  return new Promise((resolve) => {
    let settled = false;
    const done = (token) => {
      if (settled) return;
      settled = true;
      resolve(token);
    };
    let db;
    try {
      db = leveldown(leveldbDir);
      // Use the low-level callback API directly: levelup wraps open errors in
      // an unhandled 'error' event, which crashes the host when a live browser
      // holds the DB. leveldown reports the same failure through open()'s
      // callback instead.
      db.open((openErr) => {
        if (openErr) return done(null);
        db.get(DEEPSEEK_STORAGE_KEY, (getErr, value) => {
          const token = getErr ? null : decodeLocalStorageValue(value);
          try { db.close(() => {}); } catch {}
          done(token);
        });
      });
    } catch {
      done(null);
    }
  });
}

async function copyLeveldbToTemp(srcDir) {
  const tmpDir = await mkdtemp(join(tmpdir(), "chicheng-ds-"));
  const entries = await readdir(srcDir, { withFileTypes: true }).catch(() => []);
  for (const entry of entries) {
    if (entry.name === "LOCK") continue;
    const src = join(srcDir, entry.name);
    const dest = join(tmpDir, entry.name);
    if (entry.isDirectory()) {
      await mkdir(dest, { recursive: true }).catch(() => {});
      const children = await readdir(src, { withFileTypes: true }).catch(() => []);
      for (const child of children) {
        await copyFile(join(src, child.name), join(dest, child.name)).catch(() => {});
      }
    } else {
      await copyFile(src, dest).catch(() => {});
    }
  }
  return tmpDir;
}

async function readPlatformTokenFromLeveldb(dir) {
  const direct = await readTokenFromLeveldbDir(dir);
  if (direct !== null) return direct;
  // If the browser is running and holds the LevelDB lock, read a temporary copy.
  const tmpDir = await copyLeveldbToTemp(dir).catch(() => null);
  if (tmpDir === null) return null;
  try {
    return await readTokenFromLeveldbDir(tmpDir);
  } finally {
    await rm(tmpDir, { recursive: true, force: true }).catch(() => {});
  }
}

async function importDeepseekPlatformToken() {
  const dirs = await browserProfileLeveldbDirs();
  for (const dir of dirs) {
    const token = await readPlatformTokenFromLeveldb(dir);
    if (token !== null) return { token, found: true, source: dir };
  }
  return { token: null, found: false };
}

function buildApi() {
  return {
    summary: async () => {
      const now = Date.now();
      const s = fold.summary(now);
      const records = fold.allRecords();
      let deepseekInUse = false;
      for (let i = records.length - 1; i >= 0; i--) {
        const provider = records[i]?.provider;
        if (typeof provider === "string" && provider !== "" && provider !== "unknown") {
          deepseekInUse = /^deepseek(?:-|$)/i.test(provider);
          break;
        }
      }
      return {
        today: s.today,
        total: s.total,
        todayKey: s.todayKey,
        deepseekInUse,
        since: store.installedAt,
        backfill: {
          done: store.scan.finishedAt !== null,
          scannedSessions: store.scan.scannedSessions,
          scannedEvents: store.scan.scannedEvents,
          lastScanAt: store.scan.lastScanAt,
        },
      };
    },

    status: async () => ({
      storePath: STORE_PATH,
      installedAt: store.installedAt,
      days: fold.daysCount,
      watermarks: fold.watermarksCount,
      records: fold.allRecords().length,
      scanning: scanInFlight,
      scan: store.scan,
    }),

    /** Current sidebar-widget settings. */
    settings: async () => ({ settings: widgetSettings }),

    /** Validate + persist sidebar-widget settings. */
    saveSettings: async (payload) => {
      widgetSettings = sanitizeSettings(payload?.settings);
      scheduleSettingsSave();
      return { settings: widgetSettings };
    },

    /** DeepSeek open-platform balance/consumption for the hover tooltip. */
    deepseek: async (payload) => {
      const now = Date.now();
      const force = payload?.force === true;
      if (!force && deepseekCache.data !== null && now - deepseekCache.at < DEEPSEEK_CACHE_TTL_MS) {
        return { ...deepseekCache.data, cached: true };
      }
      const data = await fetchDeepseekPlatformData();
      deepseekCache = { at: now, data };
      return data;
    },

    /** Whether DEEPSEEK_PLATFORM_TOKEN is currently configured (no value). */
    platformTokenStatus: async () => {
      const ctx = currentCtx;
      if (ctx?.credentials?.describe == null) return { configured: false, writable: false };
      const desc = await ctx.credentials.describe("DEEPSEEK_PLATFORM_TOKEN");
      return { configured: desc?.configured === true, writable: desc?.writable === true };
    },

    /** Scan local Chrome/Edge profiles for a stored DeepSeek platform userToken. */
    importPlatformToken: async () => importDeepseekPlatformToken(),

    /** Persist a DeepSeek platform userToken via the credentials seam. */
    savePlatformToken: async (payload) => {
      const token = typeof payload?.token === "string" ? payload.token.trim() : "";
      if (token === "") throw new StatsError("invalid-token", "UserToken 不能为空", 400);
      const ctx = currentCtx;
      if (ctx?.credentials?.set == null) throw new StatsError("credentials-unavailable", "credentials service unavailable", 500);
      await ctx.credentials.set("DEEPSEEK_PLATFORM_TOKEN", token);
      deepseekCache = { at: 0, data: null };
      return { saved: true };
    },

    /** Detailed usage query for the stats dialog: totals, models, trend, rows. */
    usage: async (payload) => {
      const now = Date.now();
      const range = normalizeRange(payload?.range);
      const provider = typeof payload?.provider === "string" && payload.provider !== "" && payload.provider !== "all"
        ? payload.provider
        : "all";
      const from = rangeFromMs(range, now);
      const allRows = fold.queryRecords(from);
      // Provider breakdown over the FULL range (so the selector stays complete
      // while a single provider is being viewed).
      const providerMap = new Map();
      for (const record of allRows) {
        const key = record.provider ?? "unknown";
        let entry = providerMap.get(key);
        if (entry === undefined) {
          entry = { requests: 0, tokens: 0 };
          providerMap.set(key, entry);
        }
        entry.requests += 1;
        entry.tokens += record.input + record.cacheRead + record.cacheWrite + record.output;
      }
      const providers = [...providerMap.entries()]
        .map(([name, entry]) => ({ provider: name, name: providerNameOf(name), requests: entry.requests, tokens: entry.tokens }))
        .sort((a, b) => b.tokens - a.tokens);
      const rows = provider === "all"
        ? allRows
        : allRows.filter((record) => (record.provider ?? "unknown") === provider);
      let requests = rows.length;
      let input = 0;
      let cacheRead = 0;
      let cacheWrite = 0;
      let output = 0;
      let durationSum = 0;
      let durationCount = 0;
      const modelMap = new Map();
      const sessionMap = new Map();
      for (const record of rows) {
        input += record.input;
        cacheRead += record.cacheRead;
        cacheWrite += record.cacheWrite;
        output += record.output;
        if (Number.isFinite(record.duration)) {
          durationSum += record.duration;
          durationCount += 1;
        }
        let entry = modelMap.get(record.model);
        if (entry === undefined) {
          entry = { requests: 0, tokens: 0 };
          modelMap.set(record.model, entry);
        }
        entry.requests += 1;
        entry.tokens += record.input + record.cacheRead + record.cacheWrite + record.output;
        const sessionKey = record.session ?? "unknown";
        let sessionEntry = sessionMap.get(sessionKey);
        if (sessionEntry === undefined) {
          sessionEntry = {
            requests: 0,
            tokens: 0,
            input: 0,
            cacheRead: 0,
            cacheWrite: 0,
            output: 0,
            durationSum: 0,
            durationCount: 0,
            lastT: 0,
          };
          sessionMap.set(sessionKey, sessionEntry);
        }
        sessionEntry.requests += 1;
        sessionEntry.tokens += record.input + record.cacheRead + record.cacheWrite + record.output;
        sessionEntry.input += record.input;
        sessionEntry.cacheRead += record.cacheRead;
        sessionEntry.cacheWrite += record.cacheWrite;
        sessionEntry.output += record.output;
        if (Number.isFinite(record.duration)) {
          sessionEntry.durationSum += record.duration;
          sessionEntry.durationCount += 1;
        }
        if (record.t > sessionEntry.lastT) sessionEntry.lastT = record.t;
      }
      const tokens = input + cacheRead + cacheWrite + output;
      const models = [...modelMap.entries()]
        .map(([model, entry]) => ({ model, requests: entry.requests, tokens: entry.tokens }))
        .sort((a, b) => b.tokens - a.tokens);
      const sessions = [...sessionMap.entries()]
        .map(([session, entry]) => ({
          session,
          name: sessionTitles.get(session) ?? null,
          requests: entry.requests,
          tokens: entry.tokens,
          input: entry.input,
          cacheRead: entry.cacheRead,
          cacheWrite: entry.cacheWrite,
          output: entry.output,
          avgDuration: entry.durationCount > 0 ? Math.round(entry.durationSum / entry.durationCount) : null,
          lastT: entry.lastT,
        }))
        .sort((a, b) => b.tokens - a.tokens || b.lastT - a.lastT)
        .map(({ lastT, ...rest }) => rest);
      const hourly = range === "today";
      const trendMap = new Map();
      for (const record of rows) {
        const key = hourly ? hourKey(record.t) : dayKey(record.t);
        let bucket = trendMap.get(key);
        if (bucket === undefined) {
          bucket = { requests: 0, tokens: 0, input: 0, cacheRead: 0, cacheWrite: 0, output: 0 };
          trendMap.set(key, bucket);
        }
        bucket.requests += 1;
        bucket.tokens += record.input + record.cacheRead + record.cacheWrite + record.output;
        bucket.input += record.input;
        bucket.cacheRead += record.cacheRead;
        bucket.cacheWrite += record.cacheWrite;
        bucket.output += record.output;
      }
      const trend = [...trendMap.entries()]
        .map(([key, bucket]) => ({
          key,
          requests: bucket.requests,
          tokens: bucket.tokens,
          input: bucket.input,
          cacheRead: bucket.cacheRead,
          cacheWrite: bucket.cacheWrite,
          output: bucket.output,
        }))
        .sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
      const details = rows
        .slice()
        .sort((a, b) => b.t - a.t)
        .slice(0, 300)
        .map((record) => ({
          t: record.t,
          model: record.model,
          session: record.session,
          input: record.input,
          cacheRead: record.cacheRead,
          cacheWrite: record.cacheWrite,
          output: record.output,
          ttft: record.ttft ?? null,
          duration: record.duration ?? null,
        }));
      return {
        range,
        provider,
        providers,
        from: new Date(from).toISOString(),
        to: new Date(now).toISOString(),
        totals: {
          requests,
          tokens,
          input,
          cacheRead,
          cacheWrite,
          output,
          avgDuration: durationCount > 0 ? Math.round(durationSum / durationCount) : null,
        },
        models,
        sessions,
        trend,
        details,
      };
    },
  };
}

