									h(DonutChart, { items: (data?.models ?? []).map((m) => ({ name: m.model, value: m.tokens })), label: t("modelDist") }),
								),
								h("section", { className: "dshs-section" },
									h("h3", null, t("providerDist")),
									h(ModelRows, { models: (data?.providers ?? []).map((p) => ({ model: p.name ?? p.provider, requests: p.requests, tokens: p.tokens })) }),
